<script setup lang="ts">
const props=defineProps<{kind:'sorting'|'picking'|'packing'}>()
const {t}=useI18n(),route=useRoute(),router=useRouter(),staff=useStaffStore(),warehouse=useWarehouseStore(),{bizErrorMessage}=useBizError()
const ready=computed(()=>!!staff.refreshed&&!!staff.staffInfo)
const allowed=(permission:string)=>ready.value&&staff.hasPermission(permission)
const selected=ref<(string|number)[]>([])
const todayLoading=ref(false),todayError=ref('')
const printToday=async()=>{
 if(todayLoading.value||props.kind!=='picking'||!allowed('picking_read'))return
 todayLoading.value=true;todayError.value=''
 const warehouseId=warehouse.currentWarehouse?.id
 try{
  const result=await httpRequest<PaginationData>('/api/warehouse/picking/',{params:{created_today:true,warehouse_id:warehouseId,per_page:50,page:1},headers:warehouseHeaders(warehouseId),onError:e=>todayError.value=bizErrorMessage(e)})
  if(warehouseId!==warehouse.currentWarehouse?.id||!result)return
  if(!result.total){todayError.value=t('pick-today.empty');return}
  if(result.total>50){todayError.value=t('pick-today.limit');go({created_today:'true',status:undefined,keyword:undefined,print_requested:undefined});return}
  await router.push({path:'/picking/print/batch',query:{ids:result.items.map((row:any)=>row.id).join(',')}})
 }finally{todayLoading.value=false}
}
const printSelected=()=>{if(allowed('picking_read')&&selected.value.length)router.push({path:'/picking/print/batch',query:{ids:selected.value.join(',')}})}
const data=ref<PaginationData|null>(null),loading=ref(false),error=ref(''),keyword=ref(String(route.query.keyword||'')),counts=ref<Record<string,number>>({}),records=ref<Record<number,any>>({})
const statuses=['all','pending','in_progress','completed'],prefix=computed(()=>({sorting:'SORT',picking:'PICK',packing:'PACK'})[props.kind]),documentKind=computed(()=>props.kind==='sorting'?'asn':'dn')
const active=computed(()=>String(route.query.status||'all')),page=computed(()=>Number(route.query.page)||1)
const tabs=computed(()=>statuses.map(key=>({key,label:props.kind==='sorting'||key==='all'?t('common.status.'+key.replaceAll('_','-')):t('task-list.'+props.kind+'.'+key),count:counts.value[key]})))
const go=(patch:Record<string,any>,keepPage=false)=>{const query:Record<string,any>={...route.query,...patch};delete query.warehouse_id;if(!keepPage)delete query.page;for(const key of Object.keys(query))if(query[key]==null||query[key]===''||query[key]==='all')delete query[key];router.push({query})}
let previousWarehouseScope=String(warehouse.currentWarehouse?.id??useCookie('warehouse_id').value??'')
let generation=0
const load=async()=>{
 const seq=++generation;selected.value=[];loading.value=true;error.value='';data.value=null;records.value={};counts.value={}
 if(!allowed(props.kind+'_read')){loading.value=false;return}
 if(props.kind==='sorting'&&route.query.received_from&&route.query.received_to&&String(route.query.received_from)>String(route.query.received_to)){error.value=t('task-filters.invalid-range');loading.value=false;return}
 const headers=warehouseHeaders(warehouse.currentWarehouse?.id),base={...route.query,warehouse_id:warehouse.currentWarehouse?.id}
 const results=await Promise.all([httpRequest<PaginationData>('/api/warehouse/'+props.kind+'/',{params:{...base,per_page:20,page:page.value},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}),...statuses.map(status=>httpRequest<PaginationData>('/api/warehouse/'+props.kind+'/',{params:{...base,status:status==='all'?undefined:status,page:1,per_page:1},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}))])
 if(seq!==generation)return
 data.value=results[0]||null;loading.value=false
 statuses.forEach((status,index)=>{const value=results[index+1];if(value)counts.value[status]=value.total})
 if(data.value)await Promise.all(data.value.items.map(async(row:any)=>{const detail=await httpRequest<any>('/api/warehouse/'+props.kind+'/'+row.id,{headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation&&detail)records.value[row.id]=detail}))
}
const doc=(row:any)=>records.value[row.id]?.[documentKind.value]
const goodsCount=(row:any)=>{const details=doc(row)?.details;return Array.isArray(details)?new Set(details.map((detail:any)=>detail.goods_id??detail.goods?.id).filter(Boolean)).size:null}
const lastOperator=(row:any)=>{const record=records.value[row.id];const batches=record?.batches||[];return [...batches].sort((a,b)=>String(b.operation_time).localeCompare(String(a.operation_time)))[0]?.operator?.user_name||[...(record?.status_logs||[])].filter(log=>log.new_status==='in_progress'||log.new_status==='completed').sort((a,b)=>String(b.changed_at).localeCompare(String(a.changed_at)))[0]?.operator?.user_name||'—'}
const done=(row:any)=>Number(row[props.kind==='sorting'?'total_sorted_quantity':props.kind==='picking'?'total_picked_quantity':'total_packed_quantity']||0)+(props.kind==='sorting'?Number(row.total_damage_quantity||0)+Number(row.total_rejected_quantity||0):0)
const progress=(row:any)=>row.expected_quantity?Math.min(100,Math.round(done(row)/row.expected_quantity*100)):0
const columns=computed(()=>[
 {key:'task',label:t(props.kind+'.entity')},{key:'document',label:t('nav.'+documentKind.value.toUpperCase())},
 {key:'progress',label:t(props.kind==='sorting'?'operations.ui.progress':props.kind==='packing'?'operations.ui.review':'nav.goods')},
 ...(props.kind==='sorting'?[{key:'damage',label:t('operations.ui.damage'),align:'right' as const}]:props.kind==='packing'?[{key:'boxes',label:t('operations.ui.boxes')},{key:'carrier',label:t('nav.carrier')}]:[]),
 ...(props.kind!=='sorting'?[{key:'planned',label:t('dn.fields.scheduled-date')},{key:'status',label:t('common.fields.status')}]:[]),
 ...(props.kind==='picking'?[{key:'print',label:t('task-list.print')}]:[]),
 {key:'operator',label:t('operations.ui.time-operator')},{key:'next',label:t('operations.ui.next'),align:'right' as const}
])
watch(ready,()=>load());watch(()=>route.query,()=>{keyword.value=String(route.query.keyword||'');load()});watch(()=>warehouse.currentWarehouse?.id,id=>{const scope=String(id??'');const changed=scope!==previousWarehouseScope;previousWarehouseScope=scope;if(changed&&route.query.page&&Number(route.query.page)!==1)go({page:1});else load()});onMounted(load);onBeforeUnmount(()=>generation++)
useHead({title:()=>t('nav.'+props.kind)})
</script>
<template><div class="w-task-list w-scope"><header><h1>{{t('nav.'+kind)}}</h1><span>{{warehouse.currentWarehouse?.name||t('common.all-warehouse')}} · {{data?.total??'—'}}</span><WButton v-if="kind==='picking'" icon="printer" :loading="todayLoading" @click="printToday">{{t('pick-today.print')}}</WButton></header><WAlert v-if="todayError" tone="warn" :title="todayError"/><WCard flush><WTabs inset :items="tabs" :model-value="active" :label="t('common.fields.status')" @update:model-value="value=>go({status:value})" /><form class="w-task-filters" @submit.prevent="go({keyword:keyword.trim()})"><WInput v-model="keyword" type="search" :aria-label="t('common.search')" :placeholder="t(kind+'.form.placeholders.search')" @change="go({keyword:keyword.trim()})"><template #prefix><WIcon name="search" :size="16" /></template></WInput><select v-if="kind==='picking'" :value="String(route.query.print_requested??'all')" :aria-label="t('pick-audit.filter')" @change="go({print_requested:($event.target as HTMLSelectElement).value})"><option value="all">{{t('pick-audit.all')}}</option><option value="false">{{t('pick-audit.unrequested')}}</option><option value="true">{{t('pick-audit.requested')}}</option></select><WCheckbox v-if="kind==='picking'" :model-value="route.query.created_today==='true'" @update:model-value="value=>go({created_today:value?'true':undefined})">{{t('pick-today.filter')}}</WCheckbox><template v-if="kind==='sorting'"><label class="w-task-date">{{t('task-filters.received-from')}}<input type="date" :value="route.query.received_from||''" @change="go({received_from:($event.target as HTMLInputElement).value})" /></label><label class="w-task-date">{{t('task-filters.received-to')}}<input type="date" :value="route.query.received_to||''" @change="go({received_to:($event.target as HTMLInputElement).value})" /></label><WCheckbox :model-value="route.query.has_damage==='true'" @update:model-value="value=>go({has_damage:value?'true':undefined})">{{t('task-filters.damage')}}</WCheckbox><WCheckbox :model-value="route.query.spec_pending==='true'" @update:model-value="value=>go({spec_pending:value?'true':undefined})">{{t('task-filters.spec')}}</WCheckbox></template><WCheckbox v-if="kind!=='picking'" :model-value="route.query.has_variance==='true'" @update:model-value="value=>go({has_variance:value?'true':undefined})">{{t('task-filters.variance')}}</WCheckbox><WButton v-if="Object.keys(route.query).some(key=>!['page','warehouse_id'].includes(key))" type="button" variant="text" @click="go({keyword:undefined,status:undefined,has_damage:undefined,has_variance:undefined,spec_pending:undefined,received_from:undefined,received_to:undefined,print_requested:undefined,created_today:undefined})">{{t('task-filters.reset')}}</WButton></form><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><div v-if="kind==='picking'&&selected.length" class="w-task-batch"><WButton icon="printer" @click="printSelected">{{t('pick-batch.selected',{n:selected.length})}}</WButton></div><WTable :selectable="kind==='picking'" v-model:selected="selected" :rows="data?.items||[]" :columns="columns" :loading="loading" inset><template #cell-task="{row}"><NuxtLink class="w-task-name" :to="'/'+kind+'/detail/'+row.id">{{prefix}}-{{row.id}}</NuxtLink><WStatus v-if="kind==='sorting'" :tone="row.status==='completed'?'none':row.status==='in_progress'?'info':'warn'">{{kind==='sorting'?t('common.status.'+row.status.replaceAll('_','-')):t('task-list.'+kind+'.'+row.status)}}</WStatus><span class="w-task-sub">{{doc(row)?.warehouse?.name}}</span></template><template #cell-document="{row}"><NuxtLink v-if="allowed(documentKind+'_read')" class="w-task-link" :to="'/'+documentKind+'/detail/'+row[documentKind+'_id']">{{documentKind.toUpperCase()}}-{{row[documentKind+'_id']}}</NuxtLink><span v-else>{{documentKind.toUpperCase()}}-{{row[documentKind+'_id']}}</span><span class="w-task-sub">{{doc(row)?.order_number}}</span><span class="w-task-sub">{{kind==='sorting'?doc(row)?.supplier?.name:doc(row)?.recipient?.name}}</span></template><template #cell-progress="{row}"><div v-if="kind==='picking'" class="w-task-goods"><strong>{{goodsCount(row)==null?'—':t('task-list.goods',{count:goodsCount(row)})}}</strong><span>{{t('task-list.units',{count:row.expected_quantity??'—'})}}</span></div><div v-else class="w-task-progress" :class="{complete:row.status==='completed'}"><span v-if="kind==='packing'">{{t('task-filters.packed-goods',{done:row.packed_goods_count??0,total:row.expected_goods_count??0})}}</span><strong>{{done(row)}} <span>/ {{row.expected_quantity}}</span></strong><progress v-if="row.expected_quantity>0" :value="progress(row)" max="100" :aria-label="t('operations.ui.progress')" /></div><WStatus v-if="row.has_variance" tone="warn">{{t('task-filters.variance')}}</WStatus><span v-if="kind==='sorting'&&row.spec_pending_count" class="w-task-sub">{{t('task-filters.pending-spec',{count:row.spec_pending_count})}}</span></template><template #cell-damage="{row}">{{row.total_damage_quantity??'—'}}</template><template #cell-boxes="{row}">{{row.package_count??doc(row)?.packages?.length??'—'}}</template><template #cell-carrier="{row}">{{doc(row)?.carrier?.name||'—'}}</template><template #cell-planned="{row}">{{row.expected_shipping_date||'—'}}</template><template #cell-status="{row}"><WStatus :tone="row.status==='completed'?'none':row.status==='in_progress'?'info':'warn'">{{kind==='sorting'?t('common.status.'+row.status.replaceAll('_','-')):t('task-list.'+kind+'.'+row.status)}}</WStatus></template><template #cell-print="{row}"><span class="w-task-sub">{{row.print_count?t('pick-audit.count',{n:row.print_count}):t('pick-audit.unrequested')}}</span><span v-if="row.last_print_requested_at" class="w-task-sub">{{$dayjs(row.last_print_requested_at,'MM/DD HH:mm',doc(row))}}</span><WButton :to="'/picking/print/'+row.id" size="sm" variant="text">{{t('button.print')}}</WButton></template><template #cell-operator="{row}">{{row.completed_at||row.started_at?$dayjs(row.completed_at||row.started_at,'MM/DD HH:mm',doc(row)):'—'}}<span class="w-task-sub">{{lastOperator(row)}}</span></template><template #cell-next="{row}"><WButton :to="'/'+kind+'/detail/'+row.id" size="sm" variant="secondary">{{t(row.status==='completed'||!allowed(kind+'_edit')?'operations.ui.view':'operations.ui.process')}}</WButton></template></WTable><footer><WPagination :page="page" :page-size="20" :total="data?.total" show-total @update:page="value=>go({page:value},true)" /></footer></WCard></div></template>
<style scoped>
.w-task-list :deep(.w-table td){max-width:260px;white-space:normal;overflow-wrap:anywhere}.w-task-sub{max-width:240px;overflow-wrap:anywhere}
.w-task-list{display:flex;flex-direction:column;gap:16px}.w-task-list header{display:flex;gap:12px;align-items:baseline}.w-task-list h1{margin:0;font-size:24px;line-height:32px;font-weight:600}.w-task-list header>span{font-size:13px;color:var(--w-text-2)}.w-task-filters{display:flex;padding:12px 20px;border-bottom:1px solid var(--w-line)}.w-task-filters>.w-input{width:300px;max-width:100%}.w-task-list :deep(.w-table){min-width:1100px}.w-task-list :deep(.w-table-wrap.is-inset){--w-table-edge:20px}.w-task-list :deep(.w-table th){height:auto;padding-top:10px;padding-bottom:8px;line-height:16px}.w-task-list :deep(.w-table td){padding-top:12px;padding-bottom:12px;vertical-align:top}.w-task-name{display:block;font-size:14px;line-height:20px;font-weight:500;color:var(--w-text-1);text-decoration:none;margin-bottom:4px}.w-task-link{font-size:13px;color:var(--w-link);text-decoration:none}.w-task-sub{display:block;font-size:12px;line-height:18px;color:var(--w-text-3);margin-top:4px}.w-task-goods{display:flex;flex-direction:column;gap:2px;font-size:13px;line-height:20px}.w-task-goods strong{font-weight:600}.w-task-goods>span{color:var(--w-text-2)}.w-task-progress{display:flex;flex-direction:column;gap:4px;min-width:96px;max-width:96px}.w-task-progress strong{font-size:14px;font-weight:600}.w-task-progress strong span{color:var(--w-text-3);font-weight:400}.w-task-progress progress{width:100%;height:4px;border:0;border-radius:4px;overflow:hidden;background:#EDEFF3}.w-task-progress progress::-webkit-progress-bar{background:#EDEFF3}.w-task-progress progress::-webkit-progress-value{background:#7855FE}.w-task-progress.complete progress::-webkit-progress-value{background:#A0A4B0}.w-task-progress progress::-moz-progress-bar{background:#7855FE}.w-task-progress.complete progress::-moz-progress-bar{background:#A0A4B0}.w-task-list footer{padding:12px 20px;border-top:1px solid var(--w-line)}
</style>

<style scoped>.w-task-batch{padding:12px 20px;border-bottom:1px solid var(--w-line);background:var(--w-sel-soft)}</style>

<style scoped>.w-task-filters{flex-wrap:wrap;gap:12px}.w-task-filters select{max-width:100%;height:36px;border:1px solid var(--w-line);border-radius:6px;background:var(--w-bg);padding:0 10px;color:var(--w-text-1)}</style>

<style scoped>.w-task-list header{flex-wrap:wrap}.w-task-list header>.w-button{margin-left:auto}.w-task-filters{align-items:center}</style>

<style scoped>.w-task-date{display:flex;align-items:center;gap:6px;font-size:13px;flex-wrap:wrap}.w-task-date input{min-width:0;max-width:100%;height:36px;border:1px solid var(--w-line);border-radius:6px;background:var(--w-bg);color:var(--w-text-1);padding:0 8px}</style>
